    items?: DropdownMenuListItem<T>[];
    path: number[];
};
export type DropdownMenuItemMixed<T> = DropdownMenuItem<T> | Array<DropdownMenuItem<T>>;
export type DropdownMenuSize = 's' | 'm' | 'l' | 'xl';
